// intent: Verify that getting std::int64_t from an actual JSON number works fine in json_view.
#include <nlohmann/json.hpp>
#include <nlohmann/json_view.hpp>
#include <iostream>

int main() {
    try {
        auto doc = nlohmann::json_document::parse("42");
        auto view = doc.root();
        std::int64_t val = view.get<std::int64_t>();
        std::cout << "SUCCESS: " << val << std::endl;
    } catch (const std::exception& e) {
        std::cout << "EXCEPTION: " << e.what() << std::endl;
    }
}
